// packages/core/src/components/Accordion/Accordion.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";
import { AccordionContext, type AccordionVariant, AccordionItem } from "./AccordionItem";

export const accordionVariants = cva("w-full transition-all duration-200", {
  variants: {
    variant: {
      light: "divide-y divide-zinc-200/80 dark:divide-white/[0.08]",
      bordered:
        "border border-zinc-200/90 dark:border-white/[0.08] rounded-2xl overflow-hidden bg-white/80 dark:bg-[#161618]/80 backdrop-blur-xl shadow-xs divide-y divide-zinc-200/70 dark:divide-white/[0.06]",
      shadow: "space-y-3.5",
      splitted: "space-y-3.5",
    },
  },
  defaultVariants: {
    variant: "light",
  },
});

export interface AccordionProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof accordionVariants> {
  selectionMode?: "single" | "multiple";
  selectedKeys?: string[] | Set<string>;
  defaultSelectedKeys?: string[] | Set<string>;
  onSelectionChange?: (keys: string[]) => void;
  isCompact?: boolean;
  isDisabled?: boolean;
  showDivider?: boolean;
  classNames?: {
    base?: string;
  };
}

export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      className,
      classNames,
      variant = "light",
      selectionMode = "single",
      selectedKeys: propSelectedKeys,
      defaultSelectedKeys = [],
      onSelectionChange,
      isCompact = false,
      isDisabled = false,
      showDivider = true,
      children,
      ...props
    },
    ref
  ) => {
    // Normalise defaultSelectedKeys to Set
    const initialKeys = React.useMemo(() => {
      if (defaultSelectedKeys instanceof Set) return defaultSelectedKeys;
      return new Set(defaultSelectedKeys);
    }, [defaultSelectedKeys]);

    const [uncontrolledKeys, setUncontrolledKeys] = React.useState<Set<string>>(initialKeys);

    const isControlled = propSelectedKeys !== undefined;
    const currentKeys = React.useMemo(() => {
      if (!isControlled) return uncontrolledKeys;
      if (propSelectedKeys instanceof Set) return propSelectedKeys;
      return new Set(propSelectedKeys);
    }, [isControlled, propSelectedKeys, uncontrolledKeys]);

    const toggleKey = React.useCallback(
      (key: string) => {
        const next = new Set(currentKeys);
        if (selectionMode === "single") {
          if (next.has(key)) {
            next.clear();
          } else {
            next.clear();
            next.add(key);
          }
        } else {
          // multiple
          if (next.has(key)) {
            next.delete(key);
          } else {
            next.add(key);
          }
        }

        if (!isControlled) {
          setUncontrolledKeys(next);
        }
        onSelectionChange?.(Array.from(next));
      },
      [currentKeys, selectionMode, isControlled, onSelectionChange]
    );

    const contextValue = React.useMemo(
      () => ({
        selectedKeys: currentKeys,
        toggleKey,
        variant: variant || "light",
        isCompact,
        isDisabled,
        showDivider,
      }),
      [currentKeys, toggleKey, variant, isCompact, isDisabled, showDivider]
    );

    return (
      <AccordionContext.Provider value={contextValue}>
        <div
          ref={ref}
          className={cn(accordionVariants({ variant }), classNames?.base, className)}
          {...props}
        >
          {children}
        </div>
      </AccordionContext.Provider>
    );
  }
);
Accordion.displayName = "Accordion";

// packages/core/src/components/Accordion/AccordionItem.tsx
"use client";
import * as React from "react";
import { ChevronDown } from "lucide-react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type AccordionVariant = "light" | "shadow" | "bordered" | "splitted";

export interface AccordionContextValue {
  selectedKeys: Set<string>;
  toggleKey: (key: string) => void;
  variant: AccordionVariant;
  isCompact: boolean;
  isDisabled: boolean;
  showDivider: boolean;
}

export const AccordionContext = React.createContext<AccordionContextValue | null>(null);

export function useAccordionContext() {
  return React.useContext(AccordionContext);
}

export const accordionItemVariants = cva("transition-colors duration-150", {
  variants: {
    variant: {
      light: "border-b border-zinc-200/80 dark:border-white/[0.08] last:border-b-0",
      bordered: "border-b border-zinc-200/70 dark:border-white/[0.06] last:border-b-0",
      shadow:
        "bg-white dark:bg-[#161618] text-zinc-900 dark:text-zinc-100 shadow-[0_2px_8px_-2px_rgba(0,0,0,0.06),0_1px_3px_-1px_rgba(0,0,0,0.04)] hover:shadow-md border border-zinc-200/90 dark:border-white/[0.08] rounded-2xl overflow-hidden transition-all duration-200",
      splitted:
        "bg-white dark:bg-[#161618] text-zinc-900 dark:text-zinc-100 border border-zinc-200/90 dark:border-white/[0.08] rounded-2xl overflow-hidden shadow-[0_1px_4px_0_rgba(0,0,0,0.04)] hover:border-black/20 dark:hover:border-white/20 transition-all duration-200",
    },
  },
  defaultVariants: {
    variant: "light",
  },
});

export interface AccordionItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  itemKey?: string;
  value?: string;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  startContent?: React.ReactNode;
  indicator?: React.ReactNode | ((props: { isOpen: boolean }) => React.ReactNode);
  hideIndicator?: boolean;
  isDisabled?: boolean;
  classNames?: {
    base?: string;
    trigger?: string;
    titleWrapper?: string;
    title?: string;
    subtitle?: string;
    indicator?: string;
    content?: string;
  };
}

export const AccordionItem = React.forwardRef<HTMLDivElement, AccordionItemProps>(
  (
    {
      className,
      classNames,
      itemKey,
      value,
      title,
      subtitle,
      startContent,
      indicator,
      hideIndicator = false,
      isDisabled: propDisabled = false,
      children,
      id: customId,
      ...props
    },
    ref
  ) => {
    const context = useAccordionContext();
    const generatedId = React.useId();

    const actualKey = itemKey || value || customId || generatedId;

    const isOpen = context ? context.selectedKeys.has(actualKey) : false;
    const isDisabled = propDisabled || (context?.isDisabled ?? false);
    const variant = context?.variant || "light";
    const isCompact = context?.isCompact || false;

    const triggerId = `${generatedId}-trigger`;
    const contentId = `${generatedId}-content`;

    const handleToggle = () => {
      if (!isDisabled && context) {
        context.toggleKey(actualKey);
      }
    };

    return (
      <div
        ref={ref}
        className={cn(
          accordionItemVariants({ variant }),
          isDisabled ? "pointer-events-none opacity-50" : "",
          classNames?.base,
          className
        )}
        {...props}
      >
        <h3 className="m-0 p-0 font-normal">
          <button
            type="button"
            id={triggerId}
            aria-expanded={isOpen}
            aria-controls={contentId}
            aria-disabled={isDisabled ? true : undefined}
            disabled={isDisabled}
            onClick={handleToggle}
            className={cn(
              "flex w-full cursor-pointer items-center justify-between gap-3 text-left transition-all duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] select-none focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2 focus-visible:outline-none active:scale-[0.995]",
              variant === "light"
                ? isCompact
                  ? "px-1 py-2.5 hover:text-zinc-950 dark:hover:text-zinc-50"
                  : "px-1 py-4 hover:text-zinc-950 dark:hover:text-zinc-50"
                : isCompact
                  ? "rounded-xl px-4 py-3 hover:bg-black/[0.02] dark:hover:bg-white/[0.02]"
                  : "min-h-[52px] rounded-xl px-6 py-4.5 hover:bg-black/[0.02] dark:hover:bg-white/[0.02]",
              classNames?.trigger
            )}
          >
            {startContent && (
              <span
                className={cn(
                  "flex h-8 w-8 shrink-0 items-center justify-center rounded-xl transition-all duration-200",
                  isOpen
                    ? "bg-zinc-100 text-zinc-950 dark:bg-white/10 dark:text-white"
                    : "bg-black/[0.03] text-zinc-500 dark:bg-white/[0.04] dark:text-zinc-400"
                )}
              >
                {startContent}
              </span>
            )}

            <div className={cn("flex min-w-0 flex-1 flex-col text-left", classNames?.titleWrapper)}>
              <span
                className={cn(
                  "truncate tracking-tight transition-colors duration-150",
                  isOpen
                    ? "font-semibold text-zinc-950 dark:text-white"
                    : "font-medium text-zinc-900 dark:text-zinc-100",
                  isCompact ? "text-sm" : "text-base",
                  classNames?.title
                )}
              >
                {title}
              </span>
              {subtitle && (
                <span
                  className={cn(
                    "mt-0.5 text-xs text-zinc-500 dark:text-zinc-400",
                    classNames?.subtitle
                  )}
                >
                  {subtitle}
                </span>
              )}
            </div>

            {!hideIndicator && (
              <span
                aria-hidden="true"
                className={cn(
                  "flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-zinc-400 transition-all duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] dark:text-zinc-500",
                  isOpen
                    ? "rotate-180 bg-black/[0.04] text-zinc-950 dark:bg-white/10 dark:text-white"
                    : "hover:bg-black/[0.02] dark:hover:bg-white/[0.04]",
                  classNames?.indicator
                )}
              >
                {typeof indicator === "function" ? (
                  indicator({ isOpen })
                ) : indicator ? (
                  indicator
                ) : (
                  <ChevronDown className="h-4 w-4" />
                )}
              </span>
            )}
          </button>
        </h3>

        {/* Collapsible Content */}
        <div
          id={contentId}
          role="region"
          aria-labelledby={triggerId}
          className={cn(
            "grid overflow-hidden text-zinc-600 transition-all duration-200 ease-in-out dark:text-zinc-400",
            isOpen ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
          )}
        >
          <div className="overflow-hidden">
            <div
              className={cn(
                "pb-4 text-sm leading-relaxed",
                variant === "light"
                  ? isCompact
                    ? "px-1 pt-1 pb-3"
                    : "px-1 pt-1 pb-5"
                  : isCompact
                    ? "px-4 pt-1 pb-3"
                    : "px-6 pt-1 pb-5",
                classNames?.content
              )}
            >
              {children}
            </div>
          </div>
        </div>
      </div>
    );
  }
);
AccordionItem.displayName = "AccordionItem";

// packages/core/src/components/Accordion/index.ts
export * from "./AccordionItem";
export * from "./Accordion";

// packages/core/src/components/Alert/Alert.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { X } from "lucide-react";
import { cn } from "../utils/cn";

export type AlertVariant = "solid" | "flat" | "soft" | "bordered" | "outline";
export type AlertColor = "primary" | "secondary" | "success" | "danger" | "warning" | "info";

const alertVariants = cva(
  "relative flex w-full items-start gap-3.5 py-4 px-5 rounded-2xl text-sm transition-all duration-200",
  {
    variants: {
      variant: {
        solid: "shadow-xs text-white",
        flat: "shadow-none",
        soft: "shadow-none",
        bordered: "border bg-transparent",
        outline: "border bg-transparent",
      },
      color: {
        primary: "",
        secondary: "",
        success: "",
        danger: "",
        warning: "",
        info: "",
      },
    },
    compoundVariants: [
      // Solid Variants
      {
        variant: "solid",
        color: "primary",
        className: "bg-primary text-primary-foreground shadow-primary/20",
      },
      {
        variant: "solid",
        color: "secondary",
        className: "bg-secondary text-secondary-foreground shadow-secondary/20",
      },
      {
        variant: "solid",
        color: "success",
        className: "bg-emerald-600 text-white shadow-emerald-600/20 dark:bg-emerald-500",
      },
      {
        variant: "solid",
        color: "danger",
        className: "bg-rose-600 text-white shadow-rose-600/20 dark:bg-rose-500",
      },
      {
        variant: "solid",
        color: "warning",
        className: "bg-amber-500 text-zinc-950 font-bold shadow-amber-500/20 dark:bg-amber-400",
      },
      {
        variant: "solid",
        color: "info",
        className: "bg-sky-600 text-white shadow-sky-600/20 dark:bg-sky-500",
      },

      // Flat Variants
      {
        variant: ["flat", "soft"],
        color: "primary",
        className:
          "bg-indigo-50/70 text-zinc-900 border border-indigo-200/80 dark:bg-indigo-950/20 dark:text-zinc-100 dark:border-indigo-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "secondary",
        className:
          "bg-zinc-100/70 text-zinc-900 border border-zinc-200/80 dark:bg-zinc-800/30 dark:text-zinc-100 dark:border-zinc-700/30",
      },
      {
        variant: ["flat", "soft"],
        color: "success",
        className:
          "bg-emerald-50/70 text-zinc-900 border border-emerald-200/80 dark:bg-emerald-950/20 dark:text-zinc-100 dark:border-emerald-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "danger",
        className:
          "bg-rose-50/70 text-zinc-900 border border-rose-200/80 dark:bg-rose-950/20 dark:text-zinc-100 dark:border-rose-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "warning",
        className:
          "bg-amber-50/70 text-zinc-900 border border-amber-200/80 dark:bg-amber-950/20 dark:text-zinc-100 dark:border-amber-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "info",
        className:
          "bg-sky-50/70 text-zinc-900 border border-sky-200/80 dark:bg-sky-950/20 dark:text-zinc-100 dark:border-sky-500/20",
      },

      // Bordered Variants
      {
        variant: ["bordered", "outline"],
        color: "primary",
        className:
          "bg-white/70 dark:bg-[#161618]/70 backdrop-blur-md border border-indigo-500/30 text-zinc-900 dark:border-indigo-500/30 dark:text-zinc-100 shadow-2xs",
      },
      {
        variant: ["bordered", "outline"],
        color: "secondary",
        className:
          "bg-white/70 dark:bg-[#161618]/70 backdrop-blur-md border border-zinc-300/80 text-zinc-900 dark:border-zinc-700/60 dark:text-zinc-100 shadow-2xs",
      },
      {
        variant: ["bordered", "outline"],
        color: "success",
        className:
          "bg-white/70 dark:bg-[#161618]/70 backdrop-blur-md border border-emerald-500/30 text-zinc-900 dark:border-emerald-500/30 dark:text-zinc-100 shadow-2xs",
      },
      {
        variant: ["bordered", "outline"],
        color: "danger",
        className:
          "bg-white/70 dark:bg-[#161618]/70 backdrop-blur-md border border-rose-500/30 text-zinc-900 dark:border-rose-500/30 dark:text-zinc-100 shadow-2xs",
      },
      {
        variant: ["bordered", "outline"],
        color: "warning",
        className:
          "bg-white/70 dark:bg-[#161618]/70 backdrop-blur-md border border-amber-500/40 text-zinc-900 dark:border-amber-500/30 dark:text-zinc-100 shadow-2xs",
      },
      {
        variant: ["bordered", "outline"],
        color: "info",
        className:
          "bg-white/70 dark:bg-[#161618]/70 backdrop-blur-md border border-sky-500/30 text-zinc-900 dark:border-sky-500/30 dark:text-zinc-100 shadow-2xs",
      },
    ],
    defaultVariants: {
      variant: "flat",
      color: "primary",
    },
  }
);

const iconContainerMap: Record<AlertColor, string> = {
  primary:
    "bg-indigo-100/90 text-indigo-600 dark:bg-indigo-500/20 dark:text-indigo-400 ring-1 ring-indigo-500/25",
  secondary:
    "bg-zinc-200/80 text-zinc-700 dark:bg-white/10 dark:text-zinc-300 ring-1 ring-zinc-500/20",
  success:
    "bg-emerald-100/90 text-emerald-600 dark:bg-emerald-500/20 dark:text-emerald-400 ring-1 ring-emerald-500/25",
  danger:
    "bg-rose-100/90 text-rose-600 dark:bg-rose-500/20 dark:text-rose-400 ring-1 ring-rose-500/25",
  warning:
    "bg-amber-100/90 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400 ring-1 ring-amber-500/25",
  info: "bg-sky-100/90 text-sky-600 dark:bg-sky-500/20 dark:text-sky-400 ring-1 ring-sky-500/25",
};

const iconColorMap: Record<AlertColor, string> = {
  primary: "text-indigo-600 dark:text-indigo-400",
  secondary: "text-zinc-600 dark:text-zinc-400",
  success: "text-emerald-600 dark:text-emerald-400",
  danger: "text-rose-600 dark:text-rose-400",
  warning: "text-amber-600 dark:text-amber-400",
  info: "text-sky-600 dark:text-sky-400",
};

export interface AlertProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "color">,
    VariantProps<typeof alertVariants> {
  title?: React.ReactNode;
  description?: React.ReactNode;
  icon?: React.ReactNode;
  isClosable?: boolean;
  onClose?: () => void;
}

const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      className,
      variant = "flat",
      color = "primary",
      title,
      description,
      icon,
      isClosable = false,
      onClose,
      children,
      ...props
    },
    ref
  ) => {
    const [isOpen, setIsOpen] = React.useState(true);

    const handleClose = () => {
      setIsOpen(false);
      onClose?.();
    };

    if (!isOpen) return null;

    // Determine close button styling according to variant
    const getCloseButtonClass = () => {
      if (variant === "solid") {
        if (color === "warning") {
          return "text-zinc-950/70 hover:text-zinc-950 hover:bg-black/10 dark:hover:bg-black/20";
        }
        return "text-white/80 hover:text-white hover:bg-white/20 dark:hover:bg-white/15";
      }
      return "text-zinc-500 hover:text-zinc-900 hover:bg-black/5 dark:text-zinc-400 dark:hover:text-zinc-100 dark:hover:bg-white/10";
    };

    return (
      <div
        ref={ref}
        role="alert"
        className={cn(alertVariants({ variant, color, className }))}
        {...props}
      >
        {/* Left Icon Slot */}
        {icon && (
          <div
            className={cn(
              "flex h-8 w-8 shrink-0 items-center justify-center rounded-xl transition-all duration-200",
              variant === "solid"
                ? color === "warning"
                  ? "bg-zinc-950/15 text-zinc-950"
                  : "bg-white/20 text-white"
                : iconContainerMap[color || "primary"]
            )}
            aria-hidden="true"
          >
            {icon}
          </div>
        )}

        {/* Center Content Area */}
        <div className="min-w-0 flex-1 space-y-1">
          {title && (
            <h5
              className={cn(
                "text-sm leading-snug font-semibold tracking-tight",
                variant === "solid"
                  ? color === "warning"
                    ? "text-zinc-950"
                    : "text-white"
                  : "text-zinc-950 dark:text-zinc-50"
              )}
            >
              {title}
            </h5>
          )}
          {description && (
            <div
              className={cn(
                "text-xs leading-relaxed font-normal sm:text-sm",
                variant === "solid"
                  ? color === "warning"
                    ? "text-zinc-950/80"
                    : "text-white/85"
                  : "text-zinc-600 dark:text-zinc-400"
              )}
            >
              {description}
            </div>
          )}
          {children && (
            <div
              className={cn(
                "text-xs leading-relaxed font-normal sm:text-sm",
                variant === "solid"
                  ? color === "warning"
                    ? "text-zinc-950/80"
                    : "text-white/85"
                  : "text-zinc-600 dark:text-zinc-400"
              )}
            >
              {children}
            </div>
          )}
        </div>

        {/* Right Close Button */}
        {isClosable && (
          <button
            type="button"
            onClick={handleClose}
            aria-label="Close alert"
            className={cn(
              "-mt-1 -mr-1 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg transition-all focus-visible:ring-2 focus-visible:ring-zinc-950 focus-visible:outline-none active:scale-90 dark:focus-visible:ring-zinc-300",
              getCloseButtonClass()
            )}
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>
    );
  }
);

Alert.displayName = "Alert";

export { Alert, alertVariants };

"use client";
import * as React from "react";
import {
  Area,
  AreaChart as RechartsAreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  Legend,
} from "recharts";
import { cn } from "../utils/cn";
import { ChartTooltip } from "../ChartTooltip";
import { motion } from "framer-motion";
import { useId } from "react";

export interface AreaChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd" | "ref"
> {
  data: any[];
  index: string;
  categories: string[];
  colors?: string[];
  valueFormatter?: (value: number) => string;
  showXAxis?: boolean;
  showYAxis?: boolean;
  showGridLines?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  curveType?: "linear" | "natural" | "monotone" | "step";
  connectNulls?: boolean;
  strokeWidth?: number;
  strokeDasharray?: string | string[];
  type?: "default" | "stacked" | "percent";
  variant?: "default" | "sparkline";
  customTooltip?: React.ReactElement | ((props: any) => React.ReactNode);
  children?: React.ReactNode;
}

const defaultColors = [
  "var(--color-primary-500, #4F46E5)",
  "var(--color-cyan-500, #06B6D4)",
  "var(--color-success-500, #10B981)",
  "var(--color-warning-500, #F59E0B)",
  "var(--color-danger-500, #F43F5E)",
  "var(--color-secondary-500, #8B5CF6)",
];

const AreaChart = React.forwardRef<HTMLDivElement, AreaChartProps>(
  (
    {
      data,
      index,
      categories,
      colors = defaultColors,
      valueFormatter = (value: number) => value.toString(),
      showXAxis = true,
      showYAxis = true,
      showGridLines = true,
      showLegend = true,
      showTooltip = true,
      curveType = "monotone",
      connectNulls = false,
      strokeWidth = 2,
      strokeDasharray,
      type = "default",
      variant = "default",
      customTooltip,
      children,
      className,
      ...props
    },
    ref
  ) => {
    const isSparkline = variant === "sparkline";

    // Use responsive heights based on the variant
    const heightClass = isSparkline ? "h-[120px]" : "h-[350px]";
    const chartId = useId();

    return (
      <motion.div
        ref={ref}
        className={cn("w-full", heightClass, className)}
        {...props}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <RechartsAreaChart
            data={data}
            margin={{
              top: 24,
              right: 24,
              left: 24,
              bottom: showLegend && !isSparkline ? 80 : 40,
            }}
            stackOffset={type === "stacked" ? "none" : type === "percent" ? "expand" : undefined}
          >
            {showGridLines && !isSparkline && (
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={false}
                stroke="currentColor"
                className="text-zinc-200/80 dark:text-white/[0.08]"
              />
            )}

            {showXAxis && !isSparkline && (
              <XAxis
                dataKey={index}
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickMargin={16}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showYAxis && !isSparkline && (
              <YAxis
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickFormatter={valueFormatter}
                tickMargin={16}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showTooltip && (
              <Tooltip
                content={
                  customTooltip ? customTooltip : <ChartTooltip valueFormatter={valueFormatter} />
                }
              />
            )}

            {showLegend && !isSparkline && (
              <Legend
                verticalAlign="bottom"
                height={36}
                iconType="circle"
                wrapperStyle={{ fontSize: "13px", paddingTop: "20px" }}
                formatter={(value) => (
                  <span className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                    {value}
                  </span>
                )}
              />
            )}

            <defs>
              {categories.map((category, i) => (
                <linearGradient
                  key={`${chartId}-colorUv-${i}`}
                  id={`${chartId}-colorUv-${i}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop offset="5%" stopColor={colors[i % colors.length]} stopOpacity={0.25} />
                  <stop offset="95%" stopColor={colors[i % colors.length]} stopOpacity={0} />
                </linearGradient>
              ))}
            </defs>

            {categories.map((category, i) => (
              <Area
                key={category}
                type={curveType}
                dataKey={category}
                stroke={colors[i % colors.length]}
                strokeWidth={strokeWidth}
                strokeDasharray={
                  Array.isArray(strokeDasharray)
                    ? strokeDasharray[i % strokeDasharray.length]
                    : strokeDasharray
                }
                fillOpacity={1}
                fill={`url(#${chartId}-colorUv-${i})`}
                connectNulls={connectNulls}
                stackId={type === "stacked" || type === "percent" ? "1" : undefined}
                dot={false}
                activeDot={(props: any) => {
                  const { cx, cy, stroke, fill, dataKey } = props;
                  if (cx === undefined || cy === undefined || isNaN(cx) || isNaN(cy)) return null;
                  return (
                    <circle cx={cx} cy={cy} r={5} fill={colors[i % colors.length]} stroke="none" />
                  );
                }}
              />
            ))}
            {children}
          </RechartsAreaChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);

AreaChart.displayName = "AreaChart";

export { AreaChart };

