export interface ButtonProps
  extends
    Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "color">,
    VariantProps<typeof buttonVariants> {
  /**
   * Element or icon placed at the start of the button.
   */
  startContent?: React.ReactNode;
  /**
   * Element or icon placed at the end of the button.
   */
  endContent?: React.ReactNode;
  /**
   * Shows a loading spinner and disables user interaction.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Shorthand for outline variant.
   */
  outline?: boolean;
  /**
   * Shorthand for plain variant.
   */
  plain?: boolean;
  /**
   * Delegate rendering to the immediate child element using Slot pattern.
   */
  asChild?: boolean;
  /**
   * Optional link destination URL to render as an `<a>` tag.
   */
  href?: string;
  target?: string;
  rel?: string;
}

const Button = React.forwardRef<HTMLButtonElement | HTMLAnchorElement, ButtonProps>(
  (
    {
      className,
      variant = "solid",
      color = "primary",
      size = "md",
      radius = "md",
      isIconOnly = false,
      startContent,
      endContent,
      isLoading = false,
      outline,
      plain,
      asChild = false,
      children,
      disabled,
      href,
      ...props
    },
    ref
  ) => {
    // Resolve variant precedence if outline/plain shorthand was provided
    let resolvedVariant = variant;
    if (plain) resolvedVariant = "plain";
    else if (outline) resolvedVariant = "outline";
    else if (resolvedVariant === "default") resolvedVariant = "solid";

    const computedClass = cn(
      buttonVariants({
        variant: resolvedVariant,
        color,
        size,
        radius,
        isIconOnly,
        className,
      }),
      isLoading && "opacity-80 cursor-wait"
    );

    if (asChild) {
      return (
        <Slot
          ref={ref as any}
          className={computedClass}
          aria-disabled={disabled || isLoading}
          {...(props as any)}
        >
          {children}
        </Slot>
      );
    }

    // Spinner indicator
    const spinner = (
      <svg
        className="h-4 w-4 shrink-0 animate-spin text-current"
        xmlns="http://www.w3.org/2000/svg"
        fill="none"
        viewBox="0 0 24 24"
        aria-hidden="true"
      >
        <circle
          className="opacity-25"
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeWidth="4"
        />
        <path
          className="opacity-75"
          fill="currentColor"
          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
        />
      </svg>
    );

    // Standard optical frame dimensions for icons to guarantee visual balance (Gestalt Law of Proximity & Optical Centering)
    const iconFrameClass = cn(
      "inline-flex shrink-0 items-center justify-center pointer-events-none",
      size === "xs" && "w-3.5 h-3.5 [&>svg]:w-3 [&>svg]:h-3",
      size === "sm" && "w-4 h-4 [&>svg]:w-3.5 [&>svg]:h-3.5",
      size === "md" && "w-5 h-5 [&>svg]:w-4 [&>svg]:h-4",
      size === "lg" && "w-5 h-5 [&>svg]:w-5 [&>svg]:h-5",
      size === "xl" && "w-6 h-6 [&>svg]:w-5.5 [&>svg]:h-5.5"
    );

    const buttonBody = isIconOnly ? (
      isLoading ? (
        spinner
      ) : (
        children
      )
    ) : (
      <>
        {isLoading && (
          <span className={cn(iconFrameClass, "animate-in fade-in duration-150")}>{spinner}</span>
        )}
        {!isLoading && startContent && (
          <span className={iconFrameClass} aria-hidden="true">
            {startContent}
          </span>
        )}
        {children}
        {endContent && (
          <span className={iconFrameClass} aria-hidden="true">
            {endContent}
          </span>
        )}
      </>
    );

    if (href) {
      return (
        <a ref={ref as any} href={href} className={computedClass} {...(props as any)}>
          {buttonBody}
        </a>
      );
    }

    return (
      <button
        ref={ref as React.ForwardedRef<HTMLButtonElement>}
        className={computedClass}
        disabled={disabled || isLoading}
        aria-disabled={disabled || isLoading}
        aria-busy={isLoading}
        {...props}
      >
        {buttonBody}
      </button>
    );
  }
);

Button.displayName = "Button";

export { Button, buttonVariants };

