    cols: 1,
    layout: "default",
    gap: "md",
    align: "stretch",
  },
});

export interface GridProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof gridVariants> {
  /**
   * The underlying HTML element tag to render when not animated.
   * @default "div"
