        )}
      >
        {/* Current primary text (rolls up on hover) */}
        <span
          className={cn(
            "inline-block transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] will-change-transform group-hover:-translate-y-full",
            classNames?.textPrimary
          )}
        >
          {children}
        </span>

        {/* Duplicate text (rolls in from bottom on hover) */}
        <span
          aria-hidden="true"
          className={cn(
            "absolute top-full left-0 inline-block transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] will-change-transform group-hover:-translate-y-full",
            classNames?.textDuplicate
          )}
        >
          {children}
        </span>
      </span>
    );

    const content = (
      <>
        {arrowPosition === "left" && (icon || arrowElement)}
        {textElement}
        {arrowPosition === "right" && (icon || arrowElement)}
      </>
    );

    if (isLink) {
      return (
        <a
          href={href}
          target={target}
          rel={target === "_blank" ? rel || "noopener noreferrer" : rel}
          className={cn(kineticButtonVariants({ variant, size }), classNames?.base, className)}
          aria-disabled={disabled}
        >
          {content}
        </a>
      );
    }

    return (
      <button
        ref={ref}
        type="button"
        disabled={disabled}
        className={cn(kineticButtonVariants({ variant, size }), classNames?.base, className)}
        {...props}
      >
        {content}
      </button>
    );
  }
);

KineticButton.displayName = "KineticButton";

"use client";
import * as React from "react";
import {
  Line,
  LineChart as RechartsLineChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  Legend,
} from "recharts";
import { cn } from "../utils/cn";
import { ChartTooltip } from "../ChartTooltip";
import { motion } from "framer-motion";

export interface LineChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd" | "ref"
> {
  data: any[];
  index: string;
  categories: string[];
  colors?: string[];
  valueFormatter?: (value: number) => string;
  showXAxis?: boolean;
  showYAxis?: boolean;
  showGridLines?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  curveType?: "linear" | "natural" | "monotone" | "step";
  connectNulls?: boolean;
  strokeWidth?: number;
  strokeDasharray?: string | string[];
  showDots?: boolean;
  customDot?: React.ReactElement | ((props: any) => React.ReactNode);
  variant?: "default" | "sparkline";
  customTooltip?: React.ReactElement | ((props: any) => React.ReactNode);
  children?: React.ReactNode;
}

const defaultColors = [
  "var(--color-primary-500, #4F46E5)",
  "var(--color-cyan-500, #06B6D4)",
  "var(--color-success-500, #10B981)",
  "var(--color-warning-500, #F59E0B)",
  "var(--color-danger-500, #F43F5E)",
  "var(--color-secondary-500, #8B5CF6)",
];

const LineChart = React.forwardRef<HTMLDivElement, LineChartProps>(
  (
    {
      data,
      index,
      categories,
      colors = defaultColors,
      valueFormatter = (value: number) => value.toString(),
      showXAxis = true,
      showYAxis = true,
      showGridLines = true,
      showLegend = true,
      showTooltip = true,
      curveType = "monotone",
      connectNulls = false,
      strokeWidth = 2,
      strokeDasharray,
      showDots = true,
      customDot,
      variant = "default",
      customTooltip,
      children,
      className,
      ...props
    },
    ref
  ) => {
    const isSparkline = variant === "sparkline";
    const heightClass = isSparkline ? "h-[120px]" : "h-[350px]";

    return (
      <motion.div
        ref={ref}
        className={cn("w-full", heightClass, className)}
        {...props}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <RechartsLineChart
            data={data}
            margin={{
              top: 16,
              right: 16,
              left: 0,
              bottom: 0,
            }}
          >
            {showGridLines && !isSparkline && (
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={false}
                stroke="currentColor"
                className="text-zinc-200/80 dark:text-white/[0.08]"
              />
            )}

            {showXAxis && !isSparkline && (
              <XAxis
                dataKey={index}
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickMargin={12}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showYAxis && !isSparkline && (
              <YAxis
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickFormatter={valueFormatter}
                tickMargin={12}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showTooltip && (
              <Tooltip
                content={
                  customTooltip ? customTooltip : <ChartTooltip valueFormatter={valueFormatter} />
                }
              />
            )}

            {showLegend && !isSparkline && (
              <Legend
                verticalAlign="bottom"
                height={36}
                iconType="circle"
                wrapperStyle={{ fontSize: "13px", paddingTop: "20px" }}
                formatter={(value) => (
                  <span className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                    {value}
                  </span>
                )}
              />
            )}

            {categories.map((category, i) => (
              <Line
                key={category}
                type={curveType}
                dataKey={category}
                stroke={colors[i % colors.length]}
                strokeWidth={strokeWidth}
                strokeDasharray={
                  Array.isArray(strokeDasharray)
                    ? strokeDasharray[i % strokeDasharray.length]
                    : strokeDasharray
                }
                connectNulls={connectNulls}
                dot={
                  customDot
                    ? (customDot as any)
                    : showDots
                      ? (props: any) => {
                          const { cx, cy } = props;
                          if (cx === undefined || cy === undefined || isNaN(cx) || isNaN(cy))
                            return null;
                          return (
                            <circle
                              cx={cx}
                              cy={cy}
                              r={4}
                              fill={colors[i % colors.length]}
                              stroke="none"
                            />
                          );
                        }
                      : false
                }
                activeDot={(props: any) => {
                  const { cx, cy, stroke, fill, dataKey } = props;
                  if (cx === undefined || cy === undefined || isNaN(cx) || isNaN(cy)) return null;
                  return (
                    <circle cx={cx} cy={cy} r={6} fill={colors[i % colors.length]} stroke="none" />
                  );
                }}
              />
            ))}
            {children}
          </RechartsLineChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);

LineChart.displayName = "LineChart";

export { LineChart };

