  compact: "px-4 py-3 leading-normal",
  island: "p-5 leading-normal",
  compactPill: "px-3.5 py-1.5 min-h-[42px] flex items-center leading-none",
  minimal: "p-0 flex h-[44px] w-[44px] items-center justify-center leading-none",
