export type ProgressColor = "primary" | "secondary" | "success" | "warning" | "danger" | "default";
export type ProgressSize = "sm" | "md" | "lg";
export type ProgressRadius = "none" | "sm" | "md" | "lg" | "full";

export const progressTrackVariants = cva(
