"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type SectionSpacing = "none" | "xs" | "sm" | "md" | "lg" | "xl";
export type SectionVariant = "default" | "muted" | "card" | "inverted" | "obsidian";
export type SectionBordered = boolean | "top" | "bottom" | "both";

const sectionVariants = cva("relative w-full transition-colors duration-200", {
  variants: {
    spacing: {
      none: "py-0",
      xs: "py-6 sm:py-8",
      sm: "py-8 sm:py-12",
      md: "py-12 sm:py-16 lg:py-20",
      lg: "py-16 sm:py-24 lg:py-32",
      xl: "py-20 sm:py-32 lg:py-40",
    },
    variant: {
      default: "bg-transparent text-foreground",
      muted: "bg-zinc-50/80 text-foreground dark:bg-[#1a1b1e]/80",
      card: "bg-card text-card-foreground border-y border-border",
      inverted: "bg-zinc-950 text-white dark:bg-white dark:text-zinc-950",
      obsidian: "bg-[#161618] text-white",
    },
  },
  defaultVariants: {
    spacing: "md",
    variant: "default",
  },
});

export interface SectionProps
  extends React.HTMLAttributes<HTMLElement>, VariantProps<typeof sectionVariants> {
  /**
   * The underlying HTML element tag to render for semantic structure.
   * @default "section"
   */
  as?: React.ElementType;
  /**
   * Enables Apple/Mobile-safe full viewport height using 100dvh without jumpy layout.
   * @default false
   */
  fullHeight?: boolean;
  /**
   * Hairline specular border placement conforming to the 8-point spatial rhythm.
   * @default false
   */
  bordered?: SectionBordered;
}

const Section = React.forwardRef<HTMLElement, SectionProps>(
  (
    {
      as: Component = "section",
      spacing = "md",
      variant = "default",
      fullHeight = false,
      bordered = false,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const borderClass =
      bordered === true || bordered === "both"
        ? "border-y border-border"
        : bordered === "top"
          ? "border-t border-border"
          : bordered === "bottom"
            ? "border-b border-border"
            : undefined;

    return React.createElement(
      Component,
      {
        ref,
        className: cn(
          sectionVariants({ spacing, variant }),
          borderClass,
          fullHeight && "flex min-h-[100dvh] flex-col justify-center",
          className
        ),
        ...props,
      },
      children
    );
  }
);

Section.displayName = "Section";

export { Section, sectionVariants };

// packages/core/src/components/Select/Select.tsx
import React, { useState, useRef, useEffect, createContext, useContext, useId } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { ChevronDown, Check } from "lucide-react";
import { cn } from "../utils/cn";

// --- Context for Sub-components ---
interface SelectContextValue {
  selectedValue?: string;
  onSelectOption: (value: string, label: React.ReactNode) => void;
  size?: "sm" | "md" | "lg";
}

const SelectContext = createContext<SelectContextValue | null>(null);

function useSelectContext() {
  const context = useContext(SelectContext);
  if (!context) {
    throw new Error("SelectItem must be used within a Select component");
  }
  return context;
}

// --- Trigger CVA Variants ---
export const selectTriggerVariants = cva(
  "w-full inline-flex items-center justify-between text-left transition-all duration-150 outline-none select-none font-medium cursor-pointer disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        flat: "bg-muted/80 text-foreground hover:bg-muted dark:bg-[#161618] border border-black/[0.04] dark:border-white/[0.06] focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        bordered:
          "bg-transparent border border-black/[0.08] dark:border-white/[0.08] text-foreground hover:border-foreground/30 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
      },
      size: {
        sm: "h-9 px-3.5 text-xs gap-2",
        md: "h-11 px-4 text-sm gap-2.5",
        lg: "h-13 px-5 text-base gap-3",
      },
      radius: {
        none: "rounded-none",
        md: "rounded-xl",
        lg: "rounded-2xl",
        full: "rounded-full",
      },
      isInvalid: {
        true: "border-rose-600! focus-visible:ring-rose-600!",
        false: "",
      },
    },
    compoundVariants: [
      {
        radius: "full",
        size: "sm",
        className: "px-4",
      },
      {
        radius: "full",
        size: "md",
        className: "px-5",
      },
      {
        radius: "full",
        size: "lg",
        className: "px-6",
      },
    ],
    defaultVariants: {
      variant: "flat",
      size: "md",
      radius: "md",
      isInvalid: false,
    },
  }
);

export type SelectVariant = "flat" | "bordered";
export type SelectSize = "sm" | "md" | "lg";
export type SelectRadius = "none" | "md" | "lg" | "full";

export interface SelectProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof selectTriggerVariants> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  label?: React.ReactNode;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  disabled?: boolean;
  isInvalid?: boolean;
  name?: string;
  children: React.ReactNode;
}

export const Select = React.forwardRef<HTMLDivElement, SelectProps>(
  (
    {
      value: controlledValue,
      defaultValue,
      onValueChange,
      placeholder = "Select an option",
      label,
      description,
      errorMessage,
      disabled = false,
      isInvalid = false,
      variant = "flat",
      size = "md",
      radius = "md",
      className,
      children,
      name,
      id,
      ...props
    },
    ref
  ) => {
    const generatedId = useId();
    const selectId = id || generatedId;
    const [isOpen, setIsOpen] = useState(false);
    const [internalValue, setInternalValue] = useState(defaultValue || "");
    const [selectedLabel, setSelectedLabel] = useState<React.ReactNode>(null);

    const isControlled = controlledValue !== undefined;
    const activeValue = isControlled ? controlledValue : internalValue;

    const containerRef = useRef<HTMLDivElement>(null);
    const triggerRef = useRef<HTMLButtonElement>(null);

    // Extract item label if children are static or when value changes
    useEffect(() => {
      let foundLabel: React.ReactNode = null;
      React.Children.forEach(children, (child) => {
        if (
          React.isValidElement<{ value?: string; children?: React.ReactNode }>(child) &&
          child.props.value === activeValue
        ) {
          foundLabel = child.props.children;
        }
      });
      if (foundLabel) {
        setSelectedLabel(foundLabel);
      } else if (!activeValue) {
        setSelectedLabel(null);
      }
    }, [activeValue, children]);

    // Handle Click Outside to close dropdown
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
          setIsOpen(false);
        }
      };

      const handleEscape = (event: KeyboardEvent) => {
        if (event.key === "Escape" && isOpen) {
          setIsOpen(false);
          triggerRef.current?.focus();
        }
      };

      if (isOpen) {
        document.addEventListener("mousedown", handleClickOutside);
        document.addEventListener("keydown", handleEscape);
      }

      return () => {
        document.removeEventListener("mousedown", handleClickOutside);
        document.removeEventListener("keydown", handleEscape);
      };
    }, [isOpen]);

    const handleSelectOption = (itemValue: string, itemLabel: React.ReactNode) => {
      if (!isControlled) {
        setInternalValue(itemValue);
      }
      setSelectedLabel(itemLabel);
      onValueChange?.(itemValue);
      setIsOpen(false);
      triggerRef.current?.focus();
    };

    const handleToggle = () => {
      if (!disabled) {
        setIsOpen((prev) => !prev);
      }
    };

    return (
      <SelectContext.Provider
        value={{
          selectedValue: activeValue,
          onSelectOption: handleSelectOption,
          size: size || "md",
        }}
      >
        <div
          ref={containerRef}
          className={cn(
            "relative flex w-full flex-col gap-1.5",
            isOpen ? "z-40" : "z-0",
            className
          )}
          {...props}
        >
          {/* Hidden Form Input for Native Form Integration */}
          {name && <input type="hidden" name={name} value={activeValue} disabled={disabled} />}

          {/* Optional Form Label */}
          {label && (
            <label
              htmlFor={selectId}
              className="text-foreground flex items-center justify-between text-xs font-semibold select-none"
            >
              <span>{label}</span>
            </label>
          )}

          {/* Trigger Button */}
          <div className="relative w-full">
            <button
              id={selectId}
              ref={triggerRef}
              type="button"
              role="combobox"
              aria-haspopup="listbox"
              aria-expanded={isOpen}
              aria-disabled={disabled}
              aria-invalid={isInvalid}
              disabled={disabled}
              onClick={handleToggle}
              className={cn(
                selectTriggerVariants({
                  variant,
                  size,
                  radius,
                  isInvalid,
                })
              )}
            >
              <span
                className={cn(
                  "block flex-1 truncate",
                  !selectedLabel && "text-muted-foreground font-normal"
                )}
              >
                {selectedLabel || placeholder}
              </span>

              <div
                className="ml-2 flex h-5 w-5 shrink-0 items-center justify-center"
                aria-hidden="true"
              >
                <ChevronDown
                  className={cn(
                    "text-muted-foreground transition-transform duration-200",
                    size === "sm" ? "h-3.5 w-3.5" : size === "lg" ? "h-5 w-5" : "h-4 w-4",
                    isOpen && "text-foreground rotate-180"
                  )}
                />
              </div>
            </button>

            {/* Dropdown List Overlay */}
            {isOpen && (
              <div
                role="listbox"
                tabIndex={-1}
                className="animate-in fade-in-0 zoom-in-95 text-popover-foreground absolute right-0 left-0 z-50 mt-2 max-h-60 w-full overflow-y-auto rounded-2xl border border-black/[0.08] bg-white/95 p-1.5 shadow-2xl shadow-black/10 backdrop-blur-2xl duration-100 outline-none dark:border-white/[0.08] dark:bg-[#161618]/95 dark:shadow-black/60"
              >
                {children}
              </div>
            )}
          </div>

          {/* Description or Error Message */}
          {isInvalid && errorMessage ? (
            <p className="text-xs font-medium text-rose-600">{errorMessage}</p>
          ) : description ? (
            <p className="text-muted-foreground text-xs">{description}</p>
          ) : null}
        </div>
      </SelectContext.Provider>
    );
  }
);

Select.displayName = "Select";

// --- Sub-component: SelectItem ---
export interface SelectItemProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
  disabled?: boolean;
  children: React.ReactNode;
  icon?: React.ReactNode;
}

export const SelectItem = React.forwardRef<HTMLDivElement, SelectItemProps>(
  ({ value, disabled = false, children, icon, className, ...props }, ref) => {
    const { selectedValue, onSelectOption, size } = useSelectContext();
    const isSelected = selectedValue === value;

    const handleClick = () => {
      if (!disabled) {
        onSelectOption(value, children);
      }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if ((e.key === "Enter" || e.key === " ") && !disabled) {
        e.preventDefault();
        onSelectOption(value, children);
      }
    };

    return (
      <div
        ref={ref}
        role="option"
        tabIndex={disabled ? -1 : 0}
        aria-selected={isSelected}
        aria-disabled={disabled}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        className={cn(
          "flex cursor-pointer items-center justify-between rounded-xl transition-all outline-none select-none active:scale-[0.98]",
          size === "sm"
            ? "px-3 py-1.5 text-xs"
            : size === "lg"
              ? "px-4 py-3 text-base"
              : "px-3.5 py-2.5 text-sm",
          "hover:text-accent-foreground focus-visible:text-accent-foreground hover:bg-zinc-100 focus-visible:bg-zinc-100 dark:hover:bg-[#202124] dark:focus-visible:bg-[#202124]",
          isSelected
            ? "text-foreground bg-zinc-100 font-semibold dark:bg-[#202124]"
            : "text-popover-foreground font-normal",
          disabled &&
            "text-muted-foreground cursor-not-allowed opacity-40 hover:bg-transparent dark:hover:bg-transparent",
          className
        )}
        {...props}
      >
        <div className="flex items-center gap-2.5 truncate">
          {icon && <span className="text-muted-foreground shrink-0">{icon}</span>}
          <span className="truncate">{children}</span>
        </div>

        {isSelected && <Check className="text-foreground ml-2 h-4 w-4 shrink-0" />}
      </div>
    );
  }
);

SelectItem.displayName = "SelectItem";

