// ----------------------------------------------------
// Sheet Root
// ----------------------------------------------------

export interface SheetProps {
  isOpen: boolean;
  onClose?: () => void;
  side?: SheetSide;
  size?: SheetSize;
  isDismissable?: boolean;
  children: React.ReactNode;
}

export const Sheet: React.FC<SheetProps> = ({
  isOpen,
  onClose,
  side = "right",
  size = "md",
  isDismissable = true,
  children,
}) => {
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  // Keyboard Escape Handler
  React.useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isDismissable) {
        onClose?.();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, isDismissable, onClose]);

  // Lock scroll
  React.useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  if (!isOpen || !mounted) return null;

  const content = (
    <SheetContext.Provider value={{ isOpen, onClose, side, size, isDismissable }}>
      <div className="fixed inset-0 z-[100] flex">
        {/* Backdrop */}
        <div
          className="animate-in fade-in-0 fixed inset-0 bg-black/45 backdrop-blur-sm transition-opacity duration-300 ease-[cubic-bezier(0.16,1,0.3,1)]"
          aria-hidden="true"
          onClick={() => {
            if (isDismissable) onClose?.();
          }}
        />

        {/* Sheet Content Panel */}
        {children}
      </div>
    </SheetContext.Provider>
  );

  return typeof document !== "undefined" ? createPortal(content, document.body) : null;
};

