"use client";

import React, { useEffect, useRef, useState } from "react";
import createGlobe from "cobe";
import { cn } from "../utils/cn";

export interface GlobeProps {
  className?: string;
}

export const Globe: React.FC<GlobeProps> = ({ className }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pointerInteracting = useRef<number | null>(null);
  const pointerInteractionMovement = useRef(0);
  const [opacity, setOpacity] = useState(0);

  useEffect(() => {
    let phi = 0;
    let width = 0;

    if (!canvasRef.current) return;

    // Ensure initial width is captured if possible
    width = canvasRef.current.offsetWidth;
    if (width === 0) width = 800; // Fallback to 800

    const globe = createGlobe(canvasRef.current, {
      devicePixelRatio: 2,
      width: width * 2,
      height: width * 2,
      phi: 0,
      theta: 0.3,
      dark: 0,
      diffuse: 1.2,
      mapSamples: 16000,
      mapBrightness: 6,
      baseColor: [0.3, 0.3, 0.3],
      markerColor: [0.1, 0.8, 1],
      glowColor: [1, 1, 1],
      markers: [
        { location: [37.7595, -122.4367], size: 0.03 },
        { location: [40.7128, -74.006], size: 0.1 },
        { location: [51.5074, -0.1278], size: 0.05 },
        { location: [35.6895, 139.6917], size: 0.08 },
      ],
      onRender: (state: Record<string, any>) => {
        if (!pointerInteracting.current) {
          phi += 0.005;
        }
        state.phi = phi + pointerInteractionMovement.current / 200;
        state.width = width * 2;
        state.height = width * 2;
      },
    } as any);

    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        if (entry.target === canvasRef.current && entry.contentRect.width > 0) {
          width = entry.contentRect.width;
        }
      }
    });

    if (canvasRef.current) {
      resizeObserver.observe(canvasRef.current);
    }

    setTimeout(() => setOpacity(1), 200);

    return () => {
      globe.destroy();
      resizeObserver.disconnect();
    };
  }, []);

  return (
    <div className={cn("relative mx-auto aspect-square w-full max-w-[800px]", className)}>
      <canvas
        ref={canvasRef}
        onPointerDown={(e) => {
          pointerInteracting.current = e.clientX - pointerInteractionMovement.current;
          if (canvasRef.current) canvasRef.current.style.cursor = "grabbing";
        }}
        onPointerUp={() => {
          pointerInteracting.current = null;
          if (canvasRef.current) canvasRef.current.style.cursor = "grab";
        }}
        onPointerOut={() => {
          pointerInteracting.current = null;
          if (canvasRef.current) canvasRef.current.style.cursor = "grab";
        }}
        onMouseMove={(e) => {
          if (pointerInteracting.current !== null) {
            const delta = e.clientX - pointerInteracting.current;
            pointerInteractionMovement.current = delta;
          }
        }}
        onTouchMove={(e) => {
          if (pointerInteracting.current !== null && e.touches[0]) {
            const delta = e.touches[0].clientX - pointerInteracting.current;
            pointerInteractionMovement.current = delta;
          }
        }}
        style={{
          width: "100%",
          height: "100%",
          cursor: "grab",
          contain: "layout paint size",
          opacity: opacity,
          transition: "opacity 1s ease",
        }}
      />
    </div>
  );
};

"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";
import { Button } from "../Button";
import { Container } from "../Container";
import { Dropdown, DropdownTrigger, DropdownMenu, DropdownItem } from "../Dropdown";
import { motion } from "framer-motion";
import { Menu, X } from "lucide-react";

// --- Context ---

const HeroContext = React.createContext<{
  mobileMenuOpen: boolean;
  setMobileMenuOpen: React.Dispatch<React.SetStateAction<boolean>>;
}>({
  mobileMenuOpen: false,
  setMobileMenuOpen: () => {},
});

// --- Hero Container ---

const heroVariants = cva(
  "relative w-full overflow-hidden bg-white dark:bg-zinc-950 transition-colors duration-300 flex flex-col",
  {
    variants: {
      size: {
        full: "min-h-[100dvh]",
        auto: "min-h-[50dvh]",
        fixed: "h-[80dvh] min-h-[600px]",
      },
    },
    defaultVariants: {
      size: "full",
    },
  }
);

interface HeroProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof heroVariants> {
  children?: React.ReactNode;
  /** Pass false to hide the default aesthetic background blobs */
  withBlobs?: boolean;
}

const Hero = React.forwardRef<HTMLDivElement, HeroProps>(
  ({ className, size, children, withBlobs = true, ...props }, ref) => {
    const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

    return (
      <HeroContext.Provider value={{ mobileMenuOpen, setMobileMenuOpen }}>
        <div ref={ref} className={cn(heroVariants({ size }), className)} {...props}>
          {withBlobs && (
            <>
              {/* Top ambient illumination (calibrated to Hudbird brand indigo tokens) */}
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 -top-40 -z-10 transform-gpu overflow-hidden blur-3xl sm:-top-80"
              >
                <div
                  style={{
                    clipPath:
                      "polygon(74.1% 44.1%, 100% 61.6%, 97.5% 26.9%, 85.5% 0.1%, 80.7% 2%, 72.5% 32.5%, 60.2% 62.4%, 52.4% 68.1%, 47.5% 58.3%, 45.2% 34.5%, 27.5% 76.7%, 0.1% 64.9%, 17.9% 100%, 27.6% 76.8%, 76.1% 97.7%, 74.1% 44.1%)",
                  }}
                  className="from-primary/20 via-primary/10 dark:from-primary/15 dark:via-primary/5 relative left-[calc(50%-11rem)] aspect-1155/678 w-[36.125rem] -translate-x-1/2 rotate-[30deg] bg-linear-to-tr to-transparent opacity-50 sm:left-[calc(50%-30rem)] sm:w-[72.1875rem] dark:to-transparent dark:opacity-30"
                />
              </div>

              {/* Bottom ambient illumination */}
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 top-[calc(100%-13rem)] -z-10 transform-gpu overflow-hidden blur-3xl sm:top-[calc(100%-30rem)]"
              >
                <div
                  style={{
                    clipPath:
                      "polygon(74.1% 44.1%, 100% 61.6%, 97.5% 26.9%, 85.5% 0.1%, 80.7% 2%, 72.5% 32.5%, 60.2% 62.4%, 52.4% 68.1%, 47.5% 58.3%, 45.2% 34.5%, 27.5% 76.7%, 0.1% 64.9%, 17.9% 100%, 27.6% 76.8%, 76.1% 97.7%, 74.1% 44.1%)",
                  }}
                  className="from-primary/15 via-primary/5 dark:from-primary/10 dark:via-primary/5 relative left-[calc(50%+3rem)] aspect-1155/678 w-[36.125rem] -translate-x-1/2 bg-linear-to-tr to-transparent opacity-40 sm:left-[calc(50%+36rem)] sm:w-[72.1875rem] dark:to-transparent dark:opacity-20"
