Hero.displayName = "Hero";

// --- Header ---

type LinkItem = {
  label: string;
  href?: string;
  className?: string;
  items?: { label: string; href: string }[];
  onClick?: (e: React.MouseEvent) => void;
};

interface HeroHeaderProps extends React.HTMLAttributes<HTMLElement> {
  logo?: React.ReactNode;
  links?: LinkItem[];
  action?: React.ReactNode;
}

const HeroHeader = React.forwardRef<HTMLElement, HeroHeaderProps>(
  ({ className, logo, links, action, ...props }, ref) => {
    const { mobileMenuOpen, setMobileMenuOpen } = React.useContext(HeroContext);

    return (
      <header
        ref={ref}
        className={cn("absolute inset-x-0 top-0 z-50 text-zinc-900 dark:text-zinc-100", className)}
        {...props}
      >
        <nav aria-label="Global" className="flex items-center justify-between p-6 lg:px-8">
          <div className="flex lg:flex-1">{logo}</div>
          <div className="flex lg:hidden">
            <Button
              type="button"
              variant="light"
              isIconOnly
              size="sm"
              onClick={() => setMobileMenuOpen(true)}
              aria-label="Open main menu"
              className="-m-2.5 text-zinc-700 dark:text-zinc-300"
            >
              <Menu className="h-6 w-6" aria-hidden="true" />
            </Button>
          </div>
          <div className="hidden lg:flex lg:gap-x-12">
            {links?.map((item) =>
              item.items ? (
                <Dropdown key={item.label}>
                  <DropdownTrigger className="flex cursor-pointer items-center gap-1 text-sm leading-6 font-semibold transition-opacity hover:opacity-80">
                    {item.label}
                    <svg className="h-4 w-4 opacity-60" viewBox="0 0 20 20" fill="currentColor">
                      <path
                        fillRule="evenodd"
                        d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z"
                        clipRule="evenodd"
                      />
                    </svg>
                  </DropdownTrigger>
                  <DropdownMenu>
                    {item.items.map((subItem) => (
                      <DropdownItem
                        key={subItem.label}
                        onClick={() => {
                          if (subItem.href) window.location.href = subItem.href;
                        }}
                      >
                        {subItem.label}
                      </DropdownItem>
                    ))}
                  </DropdownMenu>
                </Dropdown>
              ) : (
                <a
                  key={item.label}
                  href={item.href}
                  onClick={item.onClick}
                  className={cn(
                    "text-sm leading-6 font-semibold transition-opacity hover:opacity-80",
                    item.className
                  )}
                >
                  {item.label}
                </a>
              )
            )}
          </div>
          <div className="hidden lg:flex lg:flex-1 lg:justify-end">{action}</div>
        </nav>

        {/* Mobile Menu */}
        {mobileMenuOpen && (
          <div className="lg:hidden">
            <div
              className="fixed inset-0 z-50 bg-zinc-950/80 backdrop-blur-sm"
              onClick={() => setMobileMenuOpen(false)}
            />
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="fixed inset-y-0 right-0 z-50 w-full overflow-y-auto bg-white px-6 py-6 sm:max-w-sm sm:ring-1 sm:ring-zinc-900/10 dark:bg-zinc-950 dark:sm:ring-white/10"
            >
              <div className="flex items-center justify-between">
                <div className="-m-1.5 p-1.5">
                  <span className="sr-only">Your Company</span>
                  {logo}
                </div>
                <Button
                  type="button"
                  variant="light"
                  isIconOnly
                  size="sm"
                  onClick={() => setMobileMenuOpen(false)}
                  aria-label="Close menu"
                  className="-m-2.5 text-zinc-700 dark:text-zinc-300"
                >
                  <X className="h-6 w-6" aria-hidden="true" />
                </Button>
              </div>
              <div className="mt-6 flow-root">
                <div className="-my-6 divide-y divide-zinc-500/10 dark:divide-white/10">
                  <div className="space-y-2 py-6">
                    {links?.map((item) =>
                      item.items ? (
                        <div key={item.label}>
                          <div className="-mx-3 block rounded-lg px-3 py-2 text-base leading-7 font-semibold text-zinc-900 dark:text-zinc-100">
                            {item.label}
                          </div>
                          <div className="mt-1 mb-2 ml-4 flex flex-col gap-1 border-l border-zinc-200 pl-4 dark:border-zinc-800">
                            {item.items.map((subItem) => (
                              <a
                                key={subItem.label}
                                href={subItem.href}
                                className="flex min-h-[44px] items-center rounded-lg px-3 py-2 text-sm font-medium text-zinc-600 transition-colors hover:bg-zinc-100/70 hover:text-zinc-900 dark:text-zinc-400 dark:hover:bg-zinc-900/50 dark:hover:text-zinc-100"
                              >
                                {subItem.label}
                              </a>
                            ))}
                          </div>
                        </div>
                      ) : (
                        <a
                          key={item.label}
                          href={item.href}
                          className="-mx-3 flex min-h-[44px] items-center rounded-lg px-3 py-2 text-base font-semibold text-zinc-900 transition-colors hover:bg-zinc-100/70 dark:text-zinc-100 dark:hover:bg-zinc-900/50"
                        >
                          {item.label}
                        </a>
                      )
                    )}
                  </div>
                  <div className="py-6">{action}</div>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </header>
    );
  }
);
HeroHeader.displayName = "Hero.Header";

