          <HeroImageView image={content.image} priority={false} />
          <div className="space-y-8">{items}</div>
        </Grid>
      )}
    </LandingFrame>
  );
}

"use client";
import * as React from "react";
import { Button } from "../Button";
import { MotionCrossfade } from "../Motion";
import { Tab, TabList, TabPanel, Tabs } from "../Tabs";
import { Text } from "../Text";
import type { BrandProfile, HeroContent, HeroSectionConfig } from "../CompositionSchema";
import { BrandScope, HeroSection } from "../HeroSection";
import { LandingFrame, LandingHeading } from "../LandingShared";
import "./showcase.css";

export interface LandingBuilderVariant {
  id: string;
  label: string;
  description: string;
  config: HeroSectionConfig;
}

export interface LandingBuilderShowcaseProps {
  brand: BrandProfile;
  content: HeroContent;
  variants: LandingBuilderVariant[];
  initialVariant?: string;
  builderHref: string;
}

export function LandingBuilderShowcase({
  brand,
  content,
  variants,
  initialVariant,
  builderHref,
}: LandingBuilderShowcaseProps) {
  const fallback = variants[0];
  const initial = variants.some((variant) => variant.id === initialVariant)
    ? initialVariant!
    : (fallback?.id ?? "");
  const [selected, setSelected] = React.useState(initial);
  const active = variants.find((variant) => variant.id === selected) ?? fallback;

  return (
    <LandingFrame id="builder">
      <LandingHeading
        title="Change the layout. Keep the system."
        description="Choose a hero composition and watch the same brand, content, spacing, and controls move with it."
      />
      {active ? (
        <Tabs selectedKey={active.id} onSelectionChange={setSelected} variant="underlined">
          <TabList aria-label="Hero layout">
            {variants.map((variant) => (
              <Tab key={variant.id} tabKey={variant.id}>
                {variant.label}
              </Tab>
            ))}
          </TabList>
          <Text role="status" aria-live="polite" className="sr-only">
            {active.label} preview selected.
          </Text>
          {variants.map((variant) => (
            <TabPanel key={variant.id} tabKey={variant.id} className="mt-8">
              <Text className="text-muted-foreground mb-6 max-w-[58ch] leading-relaxed">
                {variant.description}
              </Text>
              <MotionCrossfade transitionKey={variant.id}>
                <BrandScope
                  brand={brand}
                  data-builder-preview={variant.id}
                  className="hb-builder-showcase border-border overflow-hidden border"
                >
                  <HeroSection content={content} config={variant.config} headingLevel="h3" />
                </BrandScope>
              </MotionCrossfade>
            </TabPanel>
          ))}
        </Tabs>
      ) : (
        <Text role="status">Add at least one hero variant to show the builder preview.</Text>
      )}
      <Button href={builderHref} className="hb-primary hb-radius mt-8">
        Open the full page builder
      </Button>
    </LandingFrame>
  );
}

.hb-builder-showcase .hb-section {
